import re
import calendar
from datetime import date, datetime

def parse_xero_date(raw):
    if not raw:
        return None
    m = re.search(r"/Date\((-?\d+)", raw)
    if not m:
        return None
    ms = int(m.group(1))
    return datetime.utcfromtimestamp(ms / 1000).date()

def anniversary_today(start, today, n_months):
    # Is `today` exactly n_months after `start`, accounting for month-end
    # overflow (e.g. a Jan 31 start's 1-month mark lands on Feb 28/29, not
    # rolling into March).
    idx = start.month - 1 + n_months
    year = start.year + idx // 12
    month = idx % 12 + 1
    last_day = calendar.monthrange(year, month)[1]
    day = min(start.day, last_day)
    return today.year == year and today.month == month and today.day == day

def age_on(today, dob):
    age = today.year - dob.year
    if (today.month, today.day) < (dob.month, dob.day):
        age -= 1
    return age

today = date.today()
milestones = []

summary = api.connectors.invoke(server="xero-payroll-au", tool="list_employees", args={"where": 'Status=="ACTIVE"'})
employees = summary.get("Employees") or []

for emp in employees:
    employee_id = emp.get("EmployeeID")
    if not employee_id:
        continue
    detail_result = api.connectors.invoke(server="xero-payroll-au", tool="get_employee", args={"employeeId": employee_id})
    details = detail_result.get("Employees") or []
    if not details:
        continue
    detail = details[0]
    name = (f"{detail.get('FirstName','')} {detail.get('LastName','')}").strip() or "Unknown employee"

    start = parse_xero_date(detail.get("StartDate"))
    dob = parse_xero_date(detail.get("DateOfBirth"))

    if start:
        if anniversary_today(start, today, 6):
            milestones.append({
                "employee_name": name,
                "employee_id": employee_id,
                "milestone_type": "probation_step_up",
                "detail_text": f"{name} completes their 6-month probation period today ({today.isoformat()}). Confirm their pay rate steps up as agreed.",
            })
        for n in range(6, 241, 6):
            if anniversary_today(start, today, n):
                milestones.append({
                    "employee_name": name,
                    "employee_id": employee_id,
                    "milestone_type": "review_due",
                    "detail_text": f"{name} is due for their {n}-month review today ({today.isoformat()}).",
                })
                break

    if dob and (today.month, today.day) == (dob.month, dob.day):
        age_today = age_on(today, dob)
        if age_today in (18, 19, 20, 21):
            milestones.append({
                "employee_name": name,
                "employee_id": employee_id,
                "milestone_type": "junior_birthday",
                "detail_text": f"{name} turns {age_today} today ({today.isoformat()}). If they're on a junior pay rate, check whether it needs to step up.",
            })

milestone_count = len(milestones)
